<?php include __DIR__.'/../layout/header.php'; ?><div class="head"><h1>Report #<?=$report['id']?></h1><a href="index.php?page=<?= $_SESSION['user']['role']==='admin'?'manage':($_SESSION['user']['role']==='staff'?'assigned':'mine') ?>">Back</a></div><div class="card"><h2><?=e($report['title'])?></h2><p><?=nl2br(e($report['description']))?></p><div class="details"><div><b>Category</b><br><?=e($report['category'])?></div><div><b>Priority</b><br><?=e($report['priority'])?></div><div><b>Status</b><br><?=e(ucwords(str_replace('_',' ',$report['status'])))?></div><div><b>Location</b><br><?=e($report['location'])?></div></div><?php if($report['evidence']): ?><img class="evidence" src="uploads/<?=e($report['evidence'])?>"><?php endif; ?><hr><b>Action Taken</b><p><?=nl2br(e($report['action_taken']??'Not yet updated.'))?></p><?php if(in_array($_SESSION['user']['role'],['admin','staff'],true)): ?><form method="post" action="index.php?page=update"><input type="hidden" name="id" value="<?=$report['id']?>"><label>Status</label><select name="status"><?php foreach(['pending','under_review','in_progress','resolved','rejected'] as $x): ?><option value="<?=$x?>" <?=$report['status']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach; ?></select><label>Priority</label><select name="priority"><?php foreach(['low','medium','high','critical'] as $x): ?><option value="<?=$x?>" <?=$report['priority']===$x?'selected':''?>><?=e($x)?></option><?php endforeach; ?></select><?php if($_SESSION['user']['role']==='admin'): ?><label>Assign Staff</label><select name="assigned_to"><option value="">Unassigned</option><?php foreach($staff as $s): ?><option value="<?=$s['id']?>" <?=$report['assigned_to']==$s['id']?'selected':''?>><?=e($s['full_name'])?></option><?php endforeach; ?></select><?php else: ?><input type="hidden" name="assigned_to" value="<?=$report['assigned_to']?>"><?php endif; ?><label>Action Taken</label><textarea name="action_taken" rows="4"><?=e($report['action_taken']??'')?></textarea><button>Save Update</button></form><?php endif; ?></div><?php include __DIR__.'/../layout/footer.php'; ?>
